<?php
declare(strict_types=1);
require_once __DIR__.'/match-review.php';
function groupReviewEvidence(string $json,array $waiver):string
{
    $e=json_decode($json,true)?:[];foreach(['signals','conflicts'] as $key)$e[$key]=array_values(array_filter($e[$key]??[],static fn($code)=>$code!=='exact_phone'));
    return reviewEvidence(json_encode($e,JSON_THROW_ON_ERROR),$waiver).'<p class="form-text">Stripe phone is not imported; person-owned phone agreement is unavailable.</p>';
}
function renderGroupedMatchReview(array $queue,string $search,string $status): void
{
    $s=$queue['summary'];
    ?>
    <div class="match-review grouped-review">
      <header class="review-page-header"><div><span class="review-eyebrow">IDENTITY WORKSPACE</span><h1>Review people, once</h1><p>Compatible accounts and repeated waivers together. Every source record stays intact.</p></div><a class="btn btn-outline-secondary" href="matches.php?view=raw">Raw candidate view</a></header>
      <?php foreach(['match_review_notice'=>'success','match_review_error'=>'danger'] as $key=>$tone)if(isset($_SESSION[$key])): ?><div class="alert alert-<?= e($tone) ?>" role="status"><?= e($_SESSION[$key]) ?></div><?php unset($_SESSION[$key]);endif; ?>
      <p><a class="btn btn-outline-primary" href="finalize-members.php">Finalize People &amp; Members</a></p>
      <section class="group-stats" aria-label="Review workload">
      <?php foreach(['groups_needing_decision'=>'Groups needing decisions','candidate_records'=>'Candidate comparisons','waivers_represented'=>'Waivers represented','existing_people'=>'Existing BMA people','unresolved_conflicts'=>'Groups with conflicts'] as $key=>$label): ?><div class="group-stat"><strong><?= e($s[$key]) ?></strong><span><?= e($label) ?></span></div><?php endforeach; ?>
      </section>
      <?php $classification=$s['classification']; ?><section class="review-card group-preview" aria-label="Unresolved classification preview"><h2>Remaining reconciliation · <?= e($classification['examined']) ?> groups examined</h2><p>Proposals only. Completed groups are excluded; no identity or relationship changes occur on this page.</p><div class="group-metrics"><?php foreach(['same_person'=>'Same Person','parent_student'=>'Parent/Payer → Student','existing_person'=>'Existing Person','needs_review'=>'Needs Review'] as $key=>$label): ?><span><strong><?= e($classification[$key]) ?></strong> <?= e($label) ?></span><?php endforeach; ?></div><p>Actionable proposals estimate <?= e($classification['new_people_estimate']) ?> new people and <?= e($classification['new_members_estimate']) ?> new members. Shared payer proposals are counted once. Manual-review groups are excluded from these estimates.</p></section>
      <form class="review-toolbar" method="get"><div class="review-field"><label class="form-label" for="group-search">Find a person or source record</label><input class="form-control" id="group-search" name="q" value="<?= e($search) ?>" maxlength="100" placeholder="Name, email, phone, Stripe or BMA ID"></div><div><label class="form-label" for="group-status">Group status</label><select class="form-select" id="group-status" name="status"><?php foreach(['open'=>'Needs a decision','all'=>'All groups','review'=>'Review','conflict'=>'Conflict','held'=>'Held','unmatched'=>'Unmatched','confirmed'=>'Confirmed','rejected'=>'Rejected'] as $v=>$label): ?><option value="<?= e($v) ?>" <?= $status===$v?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><button class="btn btn-primary">Apply filters</button><a class="btn btn-link" href="bulk-matches.php?mode=score">Bulk score preview</a></form>
      <p class="review-muted"><?= e($queue['total']) ?> matching identity groups. Scores above 50% are eligible for review only when identity safeguards pass. Phone ownership is not used for grouping.</p>
      <?php if($queue['groups']===[]): ?><section class="review-empty"><h2>No identity groups to review</h2><p>Try another search or include all statuses. No people or associations were created.</p></section><?php endif; ?>
      <?php foreach($queue['groups'] as $g): ?><article class="review-card identity-group" data-group-id="<?= e($g['id']) ?>">
        <header class="group-card-header"><div><span class="review-eyebrow"><?= e($g['kind']==='student'?'STUDENT • SEPARATE FROM PAYER':($g['kind']==='unresolved'?'SOURCE ROLE UNRESOLVED':'PAYER / SIGNER IDENTITY')) ?></span><h2><?= e($g['name']) ?></h2><span><?= e($g['person_bma']??'BMA identity not yet verified') ?></span></div><div><?= reviewBadge($g['status']==='review'?'possible':$g['status']) ?><p class="group-confidence"><?= e(number_format($g['score_min']*100,1)) ?>–<?= e(number_format($g['score_max']*100,1)) ?>% confidence</p></div></header>
        <?php if(isset($g['classification'])): ?><section class="alert alert-light border"><h3 class="h6">Proposed: <?= e($g['classification']==='Parent/Payer → Student'?'Probable Parent/Payer → Student':$g['classification']) ?></h3><p><strong>Student/source name(s):</strong> <?= e(implode(', ',array_unique(array_column($g['waiver_records'],'source_name')))) ?><br><strong>Signer(s):</strong> <?= e(implode(', ',array_unique(array_column($g['waiver_records'],'signer_print_name')))) ?></p><ul><?php foreach($g['classification_evidence'] as $reason): ?><li><?= e($reason) ?></li><?php endforeach; ?><?php foreach($g['classification_blockers'] as $reason): ?><li>Review required: <?= e($reason) ?></li><?php endforeach; ?></ul><?php if($g['classification']==='Parent/Payer → Student'): ?><p>Proposed identities: separate payer/signer and student. Proposed edges: payer → student and the explicit source parent/guardian relationship. Administrator verification is required.</p><?php endif; ?><?php if($g['review_action']!==null): ?><a class="btn btn-outline-secondary" href="group-match.php?<?= e(http_build_query(['group'=>$g['id'],'action'=>$g['review_action']])) ?>">Review and approve classification</a><?php endif; ?></section><?php endif; ?>
        <div class="group-metrics"><span><strong><?= e(count($g['customer_records'])) ?></strong> Stripe accounts</span><span><strong><?= e($g['transaction_count']) ?></strong> transactions <small>(informational)</small></span><span><strong><?= e(count($g['waiver_records'])) ?></strong> waivers</span><span><strong><?= e(count($g['candidate_ids'])) ?></strong> comparisons</span></div>
        <div class="group-source-grid"><section><h3>Stripe payers</h3><?php foreach($g['customer_records'] as $c): ?><p><strong><?= e($c['name']?:'Name unavailable') ?></strong><br><?= e($c['email']??'Email unavailable') ?><br><code><?= e($c['stripe_customer_id']) ?></code></p><?php endforeach; ?></section><section><h3>Cognito submissions</h3><p><?php foreach($g['waiver_records'] as $w): ?><span class="badge text-bg-light">Waiver #<?= e($w['id']) ?> · <?= e($w['source_record_id']??'No submission ID') ?></span> <?php endforeach; ?></p><p>Comparisons: <?= e($g['roles']['signer']) ?> signer · <?= e($g['roles']['student']) ?> student · <?= e($g['roles']['unresolved']) ?> unresolved</p></section></div>
        <?php if($g['issues']!==[]): ?><div class="alert alert-warning"><strong><?= e(in_array($g['status'],['confirmed','rejected'],true)?'Historical comparison flags retained':'Separate review required') ?></strong><ul><?php foreach($g['issues'] as $issue): ?><li><?= e(str_replace('_',' ',$issue)) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
        <details class="group-source-details"><summary>View source records and supporting evidence</summary><?php foreach($g['candidate_rows'] as $c): $w=$g['waiver_records'][$c['cognito_waiver_id']]; ?><section class="group-candidate"><h3>Candidate #<?= e($c['id']) ?> · Waiver #<?= e($w['id']) ?> · <?= e($c['waiver_role']==='signer'?'Signer':(WaiverSourceRole::isStudent($w)?(!empty($w['student_identity_reviewed'])?'Student (BMA identity confirmed)':'Student (BMA identity unverified)'):'Unresolved source name')) ?></h3><p><?= e($w['source_name']) ?> · signer <?= e($w['signer_print_name']) ?> · relationship <?= e($w['relationship_to_student']??'Unresolved') ?> · submitted <?= e(AppTime::display($w['submitted_at'])) ?></p><p><?= e($w['contact_email']) ?> · <?= e($w['contact_phone']) ?></p><?= reviewBadge($c['match_status']) ?> <?= groupReviewEvidence((string)$c['evidence'],$w) ?></section><?php endforeach; ?></details>
        <footer class="group-actions"><?php if($g['needs_decision']): ?><a class="btn btn-primary" href="group-match.php?<?= e(http_build_query(['group'=>$g['id'],'action'=>'resolve'])) ?>">Resolve Group</a><?php endif; ?><?php if($g['eligible_ids']!==[]&&empty($g['review_action'])): ?><a class="btn btn-primary" href="group-match.php?<?= e(http_build_query(['group'=>$g['id'],'action'=>'same'])) ?>">Preview same-person decision</a><?php endif; ?><?php if($g['kind']==='student'&&$g['needs_decision']&&empty($g['review_action'])): ?><a class="btn btn-outline-primary" href="group-match.php?<?= e(http_build_query(['group'=>$g['id'],'action'=>'relationship'])) ?>">Review payer / student relationship</a><?php endif; ?><a class="btn btn-outline-secondary" href="matches.php?<?= e(http_build_query(['view'=>'raw','status'=>'all','group'=>$g['id']])) ?>">Individual review &amp; audit history</a></footer>
      </article><?php endforeach; ?>
      <?php if($queue['total']>20): ?><nav class="review-pagination" aria-label="Group pages"><?php if($queue['page']>1): ?><a class="btn btn-outline-secondary" href="?<?= e(http_build_query(['q'=>$search,'status'=>$status,'page'=>$queue['page']-1])) ?>">Previous</a><?php endif; ?><span>Page <?= e($queue['page']) ?></span><?php if($queue['page']*20<$queue['total']): ?><a class="btn btn-outline-secondary" href="?<?= e(http_build_query(['q'=>$search,'status'=>$status,'page'=>$queue['page']+1])) ?>">Next</a><?php endif; ?></nav><?php endif; ?>
    </div><?php
}
function renderGroupDecision(array $p,?array $pending,string $error=''):void
{
    $g=$p['group'];$ids=array_values(array_unique([...$p['selection'],...($p['signer_selection']??[])]));
    ?>
    <div class="match-review grouped-review"><a href="matches.php" class="btn btn-link">← Back to grouped review</a><header class="review-page-header"><div><span class="review-eyebrow">READ-ONLY PREVIEW</span><h1><?= e($g['name']) ?></h1><p><?= match($p['action']){'same','manual_same'=>'Confirm the displayed eligible roles identify one person.','different'=>'Reject these incorrect comparisons; keep existing people and source records separate.','defer'=>'Retain unresolved review status and audit your reason.',default=>'Keep payer, signer and student roles separate as explicitly verified.'} ?></p></div></header>
    <?php if($error!==''): ?><div class="alert alert-danger" role="alert"><?= e($error) ?></div><?php endif; ?>
    <section class="group-stats"><?php foreach(['people_to_create'=>'New people','people_to_reuse'=>'People to reuse','members_to_create'=>'New members'] as $key=>$label): ?><div class="group-stat"><strong><?= e($p[$key]) ?></strong><span><?= e($label) ?></span></div><?php endforeach; ?></section>
    <div class="review-card group-preview"><h2>Exact decision scope</h2><p><strong><?= e(count($ids)) ?> affected candidate records:</strong> <?= e(implode(', ',$ids)?:'None') ?></p><p><strong>Excluded / separate review:</strong> <?= e(implode(', ',$p['excluded'])?:'None') ?></p>
    <h3>Stripe accounts</h3><ul><?php foreach($p['affected_customers'] as $c): ?><li><?= e($c['name']) ?> · <?= e($c['stripe_customer_id']) ?></li><?php endforeach; ?></ul>
    <h3>Waivers</h3><ul><?php foreach($p['affected_waivers'] as $w): ?><li>#<?= e($w['id']) ?> · submission <?= e($w['source_record_id']??'Unavailable') ?> · <?= e($w['source_name']) ?> / signer <?= e($w['signer_print_name']) ?> · <?= e($w['relationship_to_student']) ?></li><?php endforeach; ?></ul>
    <?php if(in_array($p['action'],['relationship','manual_relationship'],true)): ?><p>Payer: <?= e($p['payer_bma']??'Create one reviewed payer') ?>. Student: <?= e($p['student_bma']??'Create one separate reviewed student') ?>. Only the student becomes a member. One payer relationship per distinct payer/student pair is retained.</p><?php endif; ?>
    <?php if(isset($p['input'])): ?><p><strong>Decision:</strong> <?= e(match($p['action']){'manual_same'=>'Same Person','manual_relationship'=>'Payer / Parent / Guardian of Student','different'=>'Different People / Not Related',default=>'Needs More Information'}) ?><br>Student membership verified: <?= e($p['input']['member_verified']==='1'?'Yes':'No') ?> · Parent/guardian relationship explicitly verified: <?= e($p['input']['confirm_source_relationship']==='1'?'Yes':'No') ?></p><p>Existing selections: <?= e(implode(' · ',array_filter([$p['input']['person_bma'],$p['input']['payer_bma'],$p['input']['student_bma'],$p['input']['signer_bma']]))) ?: 'Allocate or reuse as listed above' ?></p><p>Notes: <?= e($p['input']['notes']) ?></p><?php endif; ?>
    <?php if($p['blockers']!==[]): ?><div class="alert alert-warning"><strong>No grouped confirmation is available.</strong><ul><?php foreach($p['blockers'] as $b): ?><li><?= e($b) ?></li><?php endforeach; ?></ul></div><a href="matches.php?<?= e(http_build_query(['view'=>'raw','status'=>'all','group'=>$g['id']])) ?>">Review individual records</a>
    <?php elseif($pending!==null&&$error===''): ?><form method="post" class="group-confirm-form"><input type="hidden" name="csrf" value="<?= e($_SESSION['csrf']) ?>"><input type="hidden" name="operation_id" value="<?= e($pending['operation']) ?>"><div class="form-check my-3"><input class="form-check-input" type="checkbox" id="group-ack" name="acknowledge" value="1" required><label class="form-check-label" for="group-ack"><?= 'I reviewed the exact scope and approve this decision. Only explicitly verified identities, memberships and relationships will be changed.' ?></label></div><button class="btn btn-primary" name="confirm_count" value="<?= e(count($ids)) ?>">Confirm <?= e(count($ids)) ?> reviewed candidates</button><p class="form-text">No source records are deleted. Every candidate decision is audited. This changes identity associations.</p></form><?php endif; ?></div></div><script src="/assets/js/group-match-review.js" defer></script><?php
}

function renderGroupResolver(array $resolution):void
{
    $g=$resolution['group'];$personLabels=array_column($resolution['people'],'bma_person_id','id');$students=array_unique(array_column($g['waiver_records'],'source_name'));$signers=array_unique(array_column($g['waiver_records'],'signer_print_name'));
    ?><div class="match-review grouped-review"><a href="matches.php">← Back to groups</a><header class="review-page-header"><div><h1>Resolve Group</h1><p><?= e($g['name']) ?> · <?= e(count($g['candidate_ids'])) ?> comparisons · <?= e(count($g['waiver_records'])) ?> waivers</p></div></header><section class="review-card group-preview"><div class="group-source-grid"><section><h2 class="h5">Stripe payer(s)</h2><?php foreach($g['customer_records'] as $c): ?><p><strong><?= e($c['name']) ?></strong><br><?= e($c['email']) ?><br><?= e(implode(' ',array_filter([$c['address_line1'],$c['address_city'],$c['address_postal_code']]))) ?><br><?= e($c['stripe_customer_id']) ?> · <?= e($c['person_id']===null?'No BMA association':$personLabels[$c['person_id']]??'Existing BMA identity') ?></p><?php endforeach; ?></section><section><h2 class="h5">Cognito</h2><p>Recommended classification: <strong><?= e($g['classification']??$g['status']) ?></strong></p><p><strong>Student/source:</strong> <?= e(implode(', ',$students)) ?><br><strong>Signer:</strong> <?= e(implode(', ',$signers)) ?></p><?php foreach($g['waiver_records'] as $w): ?><p>Waiver #<?= e($w['id']) ?> · <?= e($w['relationship_to_student']??'Relationship unverified') ?><br><?= e($w['contact_email']) ?> · <?= e($w['contact_phone']) ?><br><?= e($w['address_text']) ?><br>Signer BMA: <?= e($personLabels[$w['signer_person_id']]??'Not linked') ?> · Student BMA: <?= e($personLabels[$w['student_person_id']]??'Not linked') ?></p><?php endforeach; ?></section></div><p>Phone is waiver contact only; Stripe phone is unavailable. Names and shared household contacts are supporting evidence, not identity proof.</p><?php foreach($g['issues'] as $issue): ?><p class="text-danger">Conflict: <?= e(str_replace('_',' ',$issue)) ?></p><?php endforeach; ?>
    <form method="post"><input type="hidden" name="phase" value="preview"><input type="hidden" name="csrf" value="<?= e($_SESSION['csrf']) ?>"><input type="hidden" name="group" value="<?= e($g['id']) ?>"><fieldset><legend class="h5">Choose the reviewed outcome</legend><?php foreach(['manual_same'=>'A. Same Person','manual_relationship'=>'B. Payer / Parent / Guardian of Student','different'=>'C. Different People / Not Related','defer'=>'D. Needs More Information'] as $value=>$label): ?><div class="form-check my-3"><input class="form-check-input" type="radio" id="choice-<?= e($value) ?>" name="decision" value="<?= e($value) ?>" required><label class="form-check-label" for="choice-<?= e($value) ?>"><?= e($label) ?></label></div><?php endforeach; ?></fieldset>
    <details class="my-3"><summary>Select an existing BMA person (optional)</summary><p>Leave blank to reuse accepted associations or allocate missing IDs safely. Existing associations cannot be reassigned here.</p><?php foreach(['person_bma'=>'Same person','payer_bma'=>'Payer','student_bma'=>'Student','signer_bma'=>'Signer (if separate from payer)'] as $field=>$label): ?><label class="form-label mt-2" for="select-<?= e($field) ?>"><?= e($label) ?></label><select class="form-select" name="<?= e($field) ?>" id="select-<?= e($field) ?>"><option value="">Reuse accepted identity / create if needed</option><?php foreach($resolution['people'] as $person): ?><option value="<?= e($person['bma_person_id']) ?>"><?= e($person['bma_person_id'].' · '.trim(implode(' ',[$person['first_name'],$person['middle_name'],$person['last_name']]))) ?></option><?php endforeach; ?></select><?php endforeach; ?></details>
    <?php foreach(['student_verified'=>'I verified the student identity. This alone does not establish membership.','member_verified'=>'I separately verified an actual academy membership relationship; create an unknown-status member if missing.','signer_is_payer'=>'I verified that the waiver signer is the payer. Otherwise keep the signer separate.','signer_is_student'=>'I verified the signer is the student (and is separate from the payer).','confirm_source_relationship'=>'I explicitly verified the stated parent/guardian relationship. Otherwise create only a payer relationship.','verify_variant'=>'I independently verified an ambiguous nickname against the selected existing BMA identity.'] as $field=>$label): ?><div class="form-check my-3"><input class="form-check-input" type="checkbox" name="<?= e($field) ?>" value="1" id="verify-<?= e($field) ?>"><label class="form-check-label" for="verify-<?= e($field) ?>"><?= e($label) ?></label></div><?php endforeach; ?><label class="form-label" for="group-notes">Review reason / notes (required for Needs More Information)</label><textarea class="form-control" id="group-notes" name="notes" maxlength="2000" rows="3"></textarea><button class="btn btn-primary mt-3">Preview Group Decision</button><p class="form-text">This prepares a read-only preview. A separate confirmation is required to save.</p></form></section></div><?php
}
